<script setup lang="ts">
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { backupPolicySchema } from '../../shared/operations'
import { apiFor } from '../utils/api'
const api = apiFor(), client = useQueryClient()
const state = useQuery({ queryKey: ['installation-operations'], queryFn: () => api('operations'), refetchInterval: query => query.state.data?.jobs.some(j => ['queued', 'running'].includes(j.status)) ? 2000 : 30_000 })
const release = useQuery({ queryKey: ['installation-release'], queryFn: () => api('installationRelease'), retry: false, staleTime: 900_000, refetchOnWindowFocus: false })
const policy = reactive({ backupHours: 0, retainBackups: 7 }), dirty = ref(false), busy = ref(false), error = ref(''), feedback = ref('')
watch(state.data, value => { if (value && !dirty.value) Object.assign(policy, value.policy) })
const active = computed(() => state.data.value?.jobs.find(j => ['queued', 'running'].includes(j.status)))
const runnerOnline = computed(() => !!state.data.value?.runnerSeen && state.data.value.runnerSeen > Date.now() - 180_000)
const available = computed(() => !busy.value && !active.value && !state.data.value?.maintenance && runnerOnline.value)
const checkpoints = computed(() => state.data.value?.jobs.filter(j => j.kind !== 'restore' && j.checkpoint && j.result?.manifestHash).slice(0, 8) || [])
const phaseLabels: Record<string, string> = { queued: 'Waiting for runner', snapshot: 'Copying frozen data and files', checkpoint: 'Recovery point verified', deploying: 'Applying the published release', verifying: 'Verifying the updated installation', 'restore-data': 'Restoring records', 'restore-files': 'Restoring private files', complete: 'Completed', cancelled: 'Cancelled' }
let request: { id: string; kind: 'backup' | 'update'; version?: string } | undefined
async function create(kind: 'backup' | 'update') {
  busy.value = true; error.value = ''; feedback.value = ''
  if (!request || request.kind !== kind || request.version !== (kind === 'update' ? release.data.value?.version : undefined)) request = { id: crypto.randomUUID(), kind, ...(kind === 'update' ? { version: release.data.value?.version } : {}) }
  try { const job = await api('operationCreate', { body: request }); request = undefined; feedback.value = job.status === 'complete' ? 'The previous request already completed. Its recovery point is shown below.' : 'Operation queued. You can close settings; the runner continues.'; await client.invalidateQueries({ queryKey: ['installation-operations'] }) }
  catch (cause) { error.value = apiError(cause) } finally { busy.value = false }
}
async function cancel(id: string) { busy.value = true; error.value = ''; try { await api('operationCancel', { params: { jobId: id } }); await state.refetch() } catch (cause) { error.value = apiError(cause) } finally { busy.value = false } }
async function savePolicy() { busy.value = true; error.value = ''; try { await api('backupPolicyUpdate', { body: policy }); dirty.value = false; feedback.value = 'Backup schedule and retention saved.'; await state.refetch() } catch (cause) { error.value = apiError(cause) } finally { busy.value = false } }
async function enableIntegrations() { busy.value = true; error.value = ''; try { await api('restoredIntegrations', { body: { enable: true } }); await state.refetch() } catch (cause) { error.value = apiError(cause) } finally { busy.value = false } }
const timestamp = (value: number) => new Date(value).toLocaleString()
</script>
<template>
  <div class="operations-settings space-y-7">
    <div><h2>Backups &amp; updates</h2><p class="section-description">Manage the whole installation: accounts, communities, messages, private files and encrypted settings.</p></div>
    <UAlert v-if="state.isError.value" color="error" title="Could not load installation operations" /><p v-else-if="state.isPending.value" role="status">Loading installation operations…</p>
    <template v-if="state.data.value">
      <dl class="grid grid-cols-2 gap-4 rounded-lg bg-elevated p-4"><div><dt class="text-muted text-xs">Installed version</dt><dd class="font-semibold">{{ state.data.value.build.version }}</dd></div><div><dt class="text-muted text-xs">Engine</dt><dd>{{ state.data.value.engine }}</dd></div><div><dt class="text-muted text-xs">API version</dt><dd>{{ state.data.value.build.apiVersion }}</dd></div><div><dt class="text-muted text-xs">Schema</dt><dd class="break-all text-xs">{{ state.data.value.build.schema }}</dd></div><div class="col-span-2"><dt class="text-muted text-xs">Installation</dt><dd class="break-all text-xs">{{ state.data.value.installationId }}</dd></div></dl>
      <UAlert v-if="!runnerOnline" color="warning" title="Operations runner is offline" description="Connect the operator runner on a trusted machine to create backups and apply updates. Deployment credentials stay there. Scheduled backups wait until it reconnects." />
      <UButton v-if="!runnerOnline" color="neutral" variant="outline" @click="state.refetch()">Refresh runner status</UButton>
      <p v-else class="text-muted text-sm">Runner connected · backups are kept outside the application by your operator.</p>
      <UAlert v-if="state.data.value.maintenance" color="warning" title="Installation is in maintenance" description="Chat writes are paused. Keep unsent drafts. A failed update or restore stays paused until the operator resumes it." />
      <section v-if="active" class="space-y-3 rounded-lg bg-elevated p-4" aria-live="polite"><h3>{{ active.kind === 'backup' ? 'Creating backup' : active.kind === 'restore' ? 'Restoring installation' : `Updating to ${active.targetVersion}` }}</h3><p>{{ phaseLabels[active.phase] || active.phase }}</p><small class="text-muted break-all">{{ active.id }}</small><UButton v-if="active.status === 'queued' || active.kind === 'backup'" color="neutral" variant="outline" :disabled="busy" @click="cancel(active.id)">Cancel operation</UButton></section>
      <UAlert v-for="job in state.data.value.jobs.slice(0, 1).filter(j => j.status === 'failed' && j.phase !== 'cancelled')" :key="job.id" color="error" title="Operation needs attention" :description="`${job.error || 'Operation failed'} · ${job.id}`" />
      <section class="space-y-4"><h3>Recovery points</h3><p class="text-muted text-sm">A backup includes accounts, every community, committed files and the keys needed to recover settings. Chat writes pause while the snapshot is copied. Recorded checkpoints below show completed verification; retention may remove older copies from the runner’s storage.</p><UButton icon="i-lucide-archive" :disabled="!available" :loading="busy" @click="create('backup')">Create backup</UButton>
        <UForm :state="policy" :schema="backupPolicySchema" class="space-y-4" @submit="savePolicy"><div class="field-grid"><UFormField name="backupHours" label="Back up every (hours)" description="0 disables scheduled backups."><UInput v-model.number="policy.backupHours" type="number" :min="0" :max="8760" class="w-full" @update:model-value="dirty = true" /></UFormField><UFormField name="retainBackups" label="Keep recent recovery points" description="At least 2. Recovery points needed by an update are also retained."><UInput v-model.number="policy.retainBackups" type="number" :min="2" :max="365" class="w-full" @update:model-value="dirty = true" /></UFormField></div><UButton type="submit" color="neutral" variant="outline" :disabled="busy || !!active">Save backup policy</UButton></UForm>
        <p v-if="!checkpoints.length" class="text-muted text-sm">No verified recovery points recorded yet.</p><ul v-else class="space-y-3"><li v-for="job in checkpoints" :key="job.id" class="rounded-lg bg-elevated p-4"><strong>{{ timestamp(job.createdAt) }}</strong><p class="text-muted text-sm">{{ job.result?.files || 0 }} files · {{ ((job.result?.bytes || 0) / 1048576).toFixed(1) }} MB · verified</p><code class="block break-all text-xs text-muted">{{ job.checkpoint }}</code></li></ul>
      </section>
      <section class="space-y-4"><h3>Installation update</h3><p class="text-muted text-sm">Choose a published release. The runner verifies its integrity and upgrade path, creates and verifies a recovery point, then applies the exact package and checks the client, backend, data, files and keys.</p><p v-if="release.isPending.value" role="status">Checking releases…</p><UAlert v-else-if="release.isError.value" color="warning" title="Could not check releases" description="The installed version continues working. Try again later." /><template v-else-if="release.data.value"><p>Latest stable: <strong>{{ release.data.value.version }}</strong></p><UAlert v-if="!release.data.value.compatible" color="warning" title="This release needs a manual compatibility review" description="Its API, schema upgrade path or engine is incompatible with this installation. The runner will refuse it before deployment." /><div class="flex flex-wrap gap-3"><UButton :to="release.data.value.url" target="_blank" rel="noopener noreferrer" color="neutral" variant="outline">Read release notes</UButton><UButton v-if="release.data.value.version !== state.data.value.build.version" :disabled="!available || !release.data.value.compatible" @click="create('update')">Back up and update to {{ release.data.value.version }}</UButton><span v-else class="text-muted self-center text-sm">You’re on the latest stable release.</span></div></template><UButton v-if="release.isError.value" color="neutral" variant="outline" @click="release.refetch()">Check again</UButton></section>
      <section v-if="state.data.value.outboundDisabled" class="space-y-4"><UAlert color="warning" title="External integrations are disabled after restore" description="Accounts and data were restored with fresh sessions. Re-enabling integrations allows explicit AI/huddle actions to use saved provider keys. Telegram login and notifications remain off until configured separately." /><UButton color="neutral" variant="outline" :disabled="busy || !!active" @click="enableIntegrations">Enable external integrations</UButton></section>
      <section class="space-y-3"><h3>Restore and runner setup</h3><p class="text-muted text-sm">Restore a verified backup into a separately provisioned empty installation. Existing installations are never overwritten. Keep recovery copies and their private keys accessible outside the deployment.</p><UButton to="https://github.com/inchidev/anycord/blob/main/docs/operations.md" target="_blank" rel="noopener noreferrer" color="neutral" variant="outline" icon="i-lucide-external-link">Operations guide</UButton></section>
    </template>
    <UAlert v-if="error" color="error" :title="error" /><UAlert v-if="feedback" color="success" :title="feedback" />
  </div>
</template>
